// Notification bell and panel visual baselines (#198): every viewport × theme project (360/768/1280,
// light and dark) with the clock frozen: the topbar bell with its unread capsule, the panel open
// with read and unread rows in Today and Earlier, and the empty panel. Rows are written straight
// into the worker database, timed around the frozen clock. Baselines live in e2e/__screenshots__
// and are only ever generated by the e2e workflow's `update_snapshots` dispatch in the pinned
// Playwright image (see e2e/README.md); without one the test is skipped.
import { existsSync } from 'node:fs';

import type { Page, TestInfo } from '@playwright/test';
import postgres from 'postgres';

import type { AsUser } from '../../fixtures/auth.ts';
import { databaseUrl } from '../../support/db-reset.ts';
import { E2E_WORKSPACES, e2eUser, expect, FROZEN_TIME, test } from '../../fixtures/index.ts';
import { shellReady } from '../shell/helpers.ts';

const WORKSPACE = E2E_WORKSPACES['chennai-solo'];
const OWNER = e2eUser('owner', 'chennai-solo');

function skipWithoutBaseline(testInfo: TestInfo, name: string) {
  const baseline = testInfo.snapshotPath(name, { kind: 'screenshot' });
  test.skip(
    testInfo.config.updateSnapshots === 'none' && !existsSync(baseline),
    'no baseline yet: dispatch the e2e workflow with update_snapshots',
  );
}

const at = (minutesAgo: number) =>
  new Date(Date.parse(FROZEN_TIME) - minutesAgo * 60_000).toISOString();

const ROWS = [
  {
    category: 'reminder.hearing',
    title: 'Hearing tomorrow: W.P. 1234/2026',
    body: 'Court 4, item 12',
    minutesAgo: 20,
    read: false,
  },
  {
    category: 'proposal.new',
    title: 'Adjournment memo drafted',
    body: 'O.S. 88/2025, ready to review',
    minutesAgo: 75,
    read: false,
  },
  {
    category: 'security.alert',
    title: 'New sign-in on Chrome',
    body: 'Chennai, India',
    minutesAgo: 140,
    read: true,
  },
  {
    category: 'member.joined',
    title: 'Arun joined the workspace',
    body: null,
    minutesAgo: 930,
    read: true,
  },
  {
    category: 'billing.notice',
    title: 'Invoice paid',
    body: 'March plan',
    minutesAgo: 2900,
    read: true,
  },
] as const;

async function seed(database: string): Promise<void> {
  const sql = postgres(databaseUrl(database, 'superuser'), { max: 1, onnotice: () => undefined });
  try {
    for (const row of ROWS) {
      await sql`
        insert into notification (workspace_id, user_id, category, title, body, read_at, created_at)
        values (
          ${WORKSPACE.id}, ${OWNER.id}, ${row.category}, ${row.title}, ${row.body},
          ${row.read ? at(row.minutesAgo) : null}, ${at(row.minutesAgo)}
        )`;
    }
  } finally {
    await sql.end();
  }
}

async function openToday(page: Page, asUser: AsUser) {
  await asUser('owner');
  await shellReady(page);
}

interface Shot {
  name: string;
  seeded: boolean;
  /** Puts the page in the state to capture. */
  setUp: (page: Page) => Promise<void>;
}

const SHOTS: readonly Shot[] = [
  {
    name: 'notifications-bell.png',
    seeded: true,
    setUp: async (page) => {
      await expect(page.locator('[data-notifications-badge]')).toHaveText('2');
    },
  },
  {
    name: 'notifications-panel.png',
    seeded: true,
    setUp: async (page) => {
      await page.locator('[data-notifications-bell]').click();
      await expect(page.locator('[data-notification-item]')).toHaveCount(ROWS.length);
    },
  },
  {
    name: 'notifications-empty.png',
    seeded: false,
    setUp: async (page) => {
      await page.locator('[data-notifications-bell]').click();
      await expect(page.getByText('You are all caught up.')).toBeVisible();
    },
  },
];

test.describe('notification visual baselines', () => {
  for (const shot of SHOTS) {
    test(
      shot.name.replace(/\.png$/, ''),
      { tag: '@visual' },
      async ({ page, asUser, db }, testInfo) => {
        skipWithoutBaseline(testInfo, shot.name);
        if (shot.seeded) await seed(db.name);
        await openToday(page, asUser);
        await shot.setUp(page);
        await expect(page).toHaveScreenshot(shot.name, { animations: 'disabled', caret: 'hide' });
      },
    );
  }
});
